<template>
	<div class="watering">
		<div class="can">
			<div class="heading"><strong>じょうろ</strong><button type="button" aria-label="育て方" title="育て方" :aria-expanded="infoOpen" @click="infoOpen = !infoOpen"><i class="ti ti-info-circle" aria-hidden="true"></i></button></div>
			<div class="controls" :aria-label="`しずく ${drops}こ`"><span class="drop"><i class="ti ti-droplet-filled" aria-hidden="true"></i></span><span class="count">{{ drops }}</span><span class="store">/{{ store }}</span><button class="pour" type="button" :disabled="busy || drops <= 0 || (target === 'self' && bloomed)" @click="emit('pour')"><i class="ti ti-droplet" aria-hidden="true"></i><span>{{ target === 'self' && bloomed ? '咲いています' : drops <= 0 ? 'しずくがありません' : target === 'festival' ? '花壇に注ぐ' : '水をあげる' }}</span></button></div>
		</div>
		<div v-if="festivalAvailable" class="targets" role="group" aria-label="注ぎ先"><button type="button" :aria-pressed="target === 'self'" @click="emit('update:modelValue', 'self')"><i class="ti ti-plant-2" aria-hidden="true"></i>自分のお花</button><button type="button" :aria-pressed="target === 'festival'" @click="emit('update:modelValue', 'festival')"><i class="ti ti-users" aria-hidden="true"></i>みんなの花壇</button></div>
		<div v-if="infoOpen" class="info" role="note"><ul><li><i class="ti ti-heart" aria-hidden="true"></i>あげなくても時間で育ち、枯れません</li><li><i class="ti ti-droplet" aria-hidden="true"></i>1しずく=約{{ pourDuration }}はやく咲く</li><li v-if="festivalAvailable"><i class="ti ti-users" aria-hidden="true"></i>花壇に注いだ分は花まつりの合計に</li></ul><button type="button" aria-label="閉じる" title="閉じる" @click="infoOpen = false"><i class="ti ti-x" aria-hidden="true"></i></button></div>
	</div>
</template>
<script setup lang="ts">
import { computed, ref } from 'vue';
const props = withDefaults(defineProps<{ drops: number; store?: number; pourMinutes?: number; bloomed?: boolean; busy?: boolean; festivalAvailable?: boolean; modelValue?: 'self' | 'festival'; animations?: boolean }>(), { store: 20, pourMinutes: 120, modelValue: 'self', bloomed: false, busy: false, festivalAvailable: true, animations: true });
const emit = defineEmits<{ 'update:modelValue': [value: 'self' | 'festival']; pour: [] }>();
const infoOpen = ref(false);
const target = computed(() => props.festivalAvailable ? props.modelValue : 'self');
const pourDuration = computed(() => { const minutes = Math.max(0, Math.ceil(props.pourMinutes)); return minutes < 60 ? `${minutes}分` : `${Math.floor(minutes / 60)}時間${minutes % 60 ? `${minutes % 60}分` : ''}`; });
</script>
<style scoped>
