der:1px solid var(--rule);border-radius:14px;background:var(--masthead);box-shadow:0 12px 32px #0002;font-size:12px;line-height:1.6}.info ul{display:grid;gap:4px;margin:0;padding:0;list-style:none}.info li{display:flex;gap:6px;overflow-wrap:anywhere}.info li i{margin-top:3px;color:var(--accent-ink)}.info>button{position:absolute;top:2px;right:2px;width:36px;height:36px;border:0;border-radius:50%;background:none;color:var(--fg-2);cursor:pointer}@container(max-width:310px){.drop{width:34px;height:34px}.count{font-size:23px}.store{font-size:13px}.controls{gap:4px}.pour{gap:4px;margin-left:2px;padding-inline:8px;font-size:12px}.store{margin-left:-2px}.targets{max-width:100%;width:100%}.targets button{flex:1;min-width:0;padding:0 5px;font-size:11px}}
